package ru.bububu.radio.core;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public final class AirMixTest {
    private AirMix.Item i(String source,String version){return new AirMix.Item(source,"a",version,source);}
    @Test public void uniqueExactVersionsAlternateAndAdmitNewRemainder(){AirMix mix=new AirMix(new Random(7));AirMix.Item a=i("one","v1"),b=i("two","v1"),c=i("one","v2");mix.enabled(true,null);mix.explicitPlay();mix.started(a);assertEquals(b,mix.next(Arrays.asList(a,a,b,c)));assertEquals(1,mix.visited());mix.started(b);assertEquals(c,mix.next(Arrays.asList(a,b,c)));mix.started(c);assertNull(mix.next(Arrays.asList(a,b,c)));assertTrue(mix.ended());AirMix.Item d=i("two","v3");assertEquals(d,mix.next(Arrays.asList(a,b,c,d)));}
    @Test public void pauseRebindAndToggleKeepPassWhileColdResetAndExplicitNewPassReset(){AirMix mix=new AirMix(new Random(1));AirMix.Item a=i("one","v");mix.enabled(true,null);mix.explicitPlay();mix.started(a);mix.enabled(false,null);mix.enabled(true,null);assertEquals(1,mix.visited());assertNull(mix.next(Arrays.asList(a)));mix.explicitPlay();assertEquals(a,mix.next(Arrays.asList(a)));assertEquals(0,mix.visited());mix.started(a);mix.coldReset();assertFalse(mix.enabled());assertEquals(0,mix.visited());mix.enabled(true,null);mix.explicitPlay();assertEquals(a,mix.next(Arrays.asList(a)));}
    @Test public void preparationNeverMarksVisitedAndExplicitReplayDoesNotClearPass(){AirMix mix=new AirMix(new Random(1));AirMix.Item a=i("one","v"),b=i("two","v");mix.enabled(true,null);mix.explicitPlay();assertNotNull(mix.next(Arrays.asList(a,b)));assertEquals(0,mix.visited());mix.started(a);mix.started(a);assertEquals(1,mix.visited());assertEquals(b,mix.next(Arrays.asList(a,b)));mix.enabled(false,null);assertNull(mix.next(Arrays.asList(a,b)));}
}
